260	    }
261	
262	    /**
263	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
264	     * the last two digits of the {@code registrationDate} year, e.g. {@code 'NSW-1A2B3C4D-M26'}. Returns
265	     * {@code null} when either the customer code or the registration date is absent.
266	     */
267	    @Named("toMembershipNumber")
268	    default String toMembershipNumber(Owner owner) {
