270	            return null;
271	        }
272	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
273	    }
274	
275	    /**
276	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
277	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
278	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
279	     * {@code 3} for tenure of more than {@code 365} days since the {@code registrationDate}. This
280	     * qualified mapping cannot observe the owner's household size (which requires counting other
281	     * owners), so it computes the points as if the owner were the only member of its household; the
282	     * controller recomputes the points with the real household size via
283	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
284	     */
285	    @Named("toMembershipPoints")
286	    default Integer toMembershipPoints(Owner owner) {
287	        if (owner == null) {
288	            return null;
289	        }
290	        return membershipPointsFor(owner, 1);
291	    }
292	
293	    /**
294	     * Returns the owner's numeric membership level, derived from its membership points: level
295	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
296	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
297	     * is not observable here and is treated as a single member.
298	     */
299	    @Named("toMembershipLevel")
300	    default Integer toMembershipLevel(Owner owner) {
301	        if (owner == null) {
302	            return null;
303	        }
304	        return membershipLevelFor(membershipPointsFor(owner, 1));
305	    }
306	
307	    /**
308	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
309	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
310	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
311	     * plus {@code 3} for tenure of more than {@code 365} days since the {@code registrationDate}.
312	     *
313	     * @param owner the owner whose points are computed, never {@code null}
314	     * @param householdSize the number of owners sharing the owner's household
315	     * @return the owner's membership points
316	     */
317	    static int membershipPointsFor(Owner owner, int householdSize) {
318	        int points = 0;
319	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
320	        if (hasEmail) {
321	            points += 2;
322	        }
323	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
324	        if (noNamesakes) {
325	            points += 1;
326	        }
327	        if (householdSize >= 3) {
328	            points += 2;
329	        }
330	        boolean tenured = owner.getRegistrationDate() != null
331	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365;
332	        if (tenured) {
333	            points += 3;
334	        }
335	        return points;
336	    }
337	
338	    /**
339	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
340	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
341	     *
342	     * @param points the owner's membership points
343	     * @return the corresponding membership level (1-4)
344	     */
345	    static int membershipLevelFor(int points) {
346	        if (points <= 1) {
347	            return 1;
348	        }
349	        if (points <= 3) {
350	            return 2;
351	        }
352	        if (points <= 5) {
353	            return 3;
354	        }
355	        return 4;
356	    }
357	
358	    /**
359	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
360	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
361	     * absent.
362	     */
363	    @Named("toCheckDigit")
364	    default Integer toCheckDigit(Owner owner) {
365	        if (owner == null || owner.getCustomerCode() == null) {
366	            return null;
367	        }
368	        int sum = 0;
369	        boolean dbl = true;
370	        String code = owner.getCustomerCode();
371	        for (int i = code.length() - 1; i >= 0; i--) {
372	            char c = code.charAt(i);
373	            if (c < '0' || c > '9') {
374	                continue;
375	            }
376	            int d = c - '0';
377	            if (dbl) {
378	                d *= 2;
379	                if (d > 9) {
380	                    d -= 9;
381	                }
382	            }
383	            sum += d;
384	            dbl = !dbl;
385	        }
386	        return (10 - (sum % 10)) % 10;
387	    }
388	
389	    private static String initial(String name) {
390	        if (name == null || name.isEmpty()) {
391	            return "";
392	        }
393	        return Character.toUpperCase(name.charAt(0)) + ".";
394	    }
395	
396	    Owner toOwner(OwnerDto ownerDto);
397	
398	    @Mapping(target = "id", ignore = true)
399	    @Mapping(target = "pets", ignore = true)
400	    Owner toOwner(OwnerFieldsDto ownerDto);
401	
402	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
403	
404	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
